// One-time (and re-runnable) IndexNow submission -- notifies Bing/Yandex/etc.
// of every real, indexable URL on the site in a single batch request. The
// key verification file (public/<key>.txt) is already generated by
// gen-agent-files.mjs; this script is the missing "actually submit URLs"
// half of IndexNow setup. Safe to re-run after any content change (new
// products/posts/etc.) -- IndexNow submission is idempotent, not a one-shot.
import site from '../src/data/site.json' with { type: 'json' };
import products from '../src/data/products.json' with { type: 'json' };
import categories from '../src/data/categories.json' with { type: 'json' };
import posts from '../src/data/posts.json' with { type: 'json' };

const SITE = site;
const STATIC_PAGES = ['', 'shop', 'shop/brand', 'premium', 'compare', 'about', 'blog', 'contact', 'wholesale', 'faq', 'reviews', 'shipping', 'refund', 'privacy', 'terms'];

function absUrl(path) {
  return `https://${SITE.domain}${path}`;
}

function brandSlug(name) {
  return name.toLowerCase().replace(/&/g, 'and').replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
}

const brandNames = Array.from(new Set(products.map((p) => p.brand)));

const urls = [
  ...STATIC_PAGES.map((p) => absUrl(p ? `/${p}/` : '/')),
  ...categories.map((c) => absUrl(`/shop/${c.slug}/`)),
  ...brandNames.map((name) => absUrl(`/shop/brand/${brandSlug(name)}/`)),
  ...products.map((p) => absUrl(`/product/${p.slug}/`)),
  ...posts.map((p) => absUrl(`/blog/${p.slug}/`)),
];

const body = {
  host: SITE.domain,
  key: SITE.indexNowKey,
  keyLocation: absUrl(`/${SITE.indexNowKey}.txt`),
  urlList: urls,
};

console.log(`Submitting ${urls.length} URLs to IndexNow for host ${SITE.domain}...`);

const res = await fetch('https://api.indexnow.org/indexnow', {
  method: 'POST',
  headers: { 'Content-Type': 'application/json; charset=utf-8' },
  body: JSON.stringify(body),
});

console.log(`IndexNow response: ${res.status} ${res.statusText}`);
const text = await res.text();
if (text) console.log(text);

if (res.status === 200 || res.status === 202) {
  console.log('Submission accepted.');
} else {
  console.log('Submission was NOT accepted -- check host/key/keyLocation match the live site.');
  process.exitCode = 1;
}
